<div class="fullscreen-control relative shrink-0">
    <p data-fullscreen-status role="status" hidden class="fullscreen-status">Layar penuh tidak tersedia di browser ini.</p>
    <button type="button" data-fullscreen-toggle aria-label="Layar penuh" aria-pressed="false" title="Layar penuh" class="fullscreen-toggle inline-flex size-11 items-center justify-center text-hospital-deep transition-colors hover:text-hospital focus-visible:outline-3 focus-visible:outline-offset-3 focus-visible:outline-hospital disabled:cursor-not-allowed disabled:opacity-60">
        <svg data-fullscreen-enter-icon aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" class="size-5"><path d="M8 3H3v5M16 3h5v5M3 16v5h5m13-5v5h-5" /></svg>
        <svg data-fullscreen-exit-icon aria-hidden="true" hidden viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" class="size-5"><path d="M3 8h5V3m13 5h-5V3M8 21v-5H3m13 5v-5h5" /></svg>
        <span data-fullscreen-label class="sr-only">Layar penuh</span>
    </button>
</div>
